53:     public function resolve_shipping_size($planCode, $package)
54:     {
55:         $total_weight = 0;
56:         $packages = [];
57:         $default_width_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_width');
58:         $default_height_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_height');
59:         $default_length_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_length');
60:         $default_width = $default_width_cfg && is_numeric($default_width_cfg) ? (float)$default_width_cfg : 10;
61:         $default_height = $default_height_cfg && is_numeric($default_height_cfg) ? (float)$default_height_cfg : 10;
62:         $default_length = $default_length_cfg && is_numeric($default_length_cfg) ? (float)$default_length_cfg : 10;
63:         $dimension_unit = get_option('woocommerce_dimension_unit');
64: 
65:         foreach ($package['contents'] as $content) {
66:             $quantity = $content['quantity']; // get quantity
67:             $product = $content['data']; // get the WC_Product_Simple object
68:             $virtual = $product->is_virtual();
69:             $product_weight = $product->get_weight(); // get the product weight
70:             if ($product_weight) {
71:                 // Add the line item weight to the total weight calculation
72:                 $total_weight += floatval($product_weight * $quantity);
73:             }
74:             $length = $product->get_length() ? (float)wc_get_dimension($product->get_length(), 'cm', $dimension_unit) : 0;
75:             $width = $product->get_width() ? (float)wc_get_dimension($product->get_width(), 'cm', $dimension_unit) : 0;
76:             $height = $product->get_height() ? (float)wc_get_dimension($product->get_height(), 'cm', $dimension_unit) : 0;
77:             if (!$virtual) {
78:                 $packages[] = [$width > 0 ? $width : $default_width, $height > 0 ? $height : $default_height, $length > 0 ? $length : $default_length, $quantity];
79:             }
80:         }
81:         if (empty($packages)) return null;
82: 
83:         $total_weight_in_g = apply_filters('woo_lithuaniapost_admin_util_convert_to_grams', $total_weight);
84: 
85:         $packages = self::package_size($packages, $planCode, $total_weight_in_g);
86:         return !empty($packages) ? strtoupper($packages[0]) : null;
87:     }
