92:         $default_width_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_width');
93:         $default_height_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_height');
94:         $default_length_cfg = Woo_Lithuaniapost_Admin_Settings::get_option('dimension_length');
95:         $default_width = $default_width_cfg && is_numeric($default_width_cfg) ? (float)$default_width_cfg : 10;
96:         $default_height = $default_height_cfg && is_numeric($default_height_cfg) ? (float)$default_height_cfg : 10;
97:         $default_length = $default_length_cfg && is_numeric($default_length_cfg) ? (float)$default_length_cfg : 10;
98:         $dimension_unit = get_option('woocommerce_dimension_unit');
99:         $plan_code = $lp_shipping_method->plan;
100: 
101:         $total_weight_in_g = apply_filters('woo_lithuaniapost__order_action_get_order_weight_in_g', $order);
102: 
103:         foreach ($order->get_items() as $item_id => $product_item) {
104:             $product = $product_item->get_product(); // get the WC_Product object
105:             $virtual = $product->is_virtual() === true;
106:             $length = $product->get_length() ? (float)wc_get_dimension($product->get_length(), 'cm', $dimension_unit) : 0;
107:             $width = $product->get_width() ? (float)wc_get_dimension($product->get_width(), 'cm', $dimension_unit) : 0;
108:             $height = $product->get_height() ? (float)wc_get_dimension($product->get_height(), 'cm', $dimension_unit) : 0;
109:             if (!$virtual) {
110:                 $packages[] = [$width > 0 ? $width : $default_width, $height > 0 ? $height : $default_height, $length > 0 ? $length : $default_length, $product_item->get_quantity() ?? 1];
111:             }
112:         }
113:         if (empty($packages)) return null;
114:         $packages = $this->package_size($packages, $plan_code, $total_weight_in_g);
